return ['domain'=>'tranzly','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T13:56:07+00:00','po-revision-date'=>'2026-09-26T13:56:07+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Wielojęzyczny WordPress, jeden post na język: powiązane tłumaczenia postów, stron, kategorii, tekstu mediów, widżetów i tytułu witryny, z zaimportowanymi starymi tłumaczeniami Tranzly.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Dostawcy AI','The makers of ChatGPT. A good all-rounder.'=>'Twórcy ChatGPT. Dobry wszechstronny wybór.','The makers of Claude. Strong at writing and careful reasoning.'=>'Twórcy Claude. Silni w pisaniu i starannym wnioskowaniu.','Google\'s Gemini models. Fast and inexpensive.'=>'Modele Gemini od Google. Szybkie i niedrogie.','A European AI company with fast, inexpensive models.'=>'Europejska firma zajmująca się sztuczną inteligencją oferująca szybkie i niedrogie modele.','Low-cost models that are good at writing and code.'=>'Niedrogie modele świetnie radzące sobie z pisaniem tekstów i kodem.','One key for models from many different providers.'=>'Jeden klucz do modeli od wielu różnych dostawców.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Dowolna usługa działająca tak samo jak interfejs API OpenAI, w tym model uruchomiony na własnym komputerze lub serwerze.','General (used when nothing more specific is set)'=>'Ogólne (stosowane, gdy nie ustawiono nic bardziej szczegółowego)','Writing and rewriting'=>'Zapisywanie i ponowne zapisywanie','Translation'=>'Tłumaczenie','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Przepraszamy, nie masz uprawnień dostępu do tej strony.','These settings are shared by every plugin that uses them: %s.'=>'Te ustawienia są wspólne dla wszystkich wtyczek, które z nich korzystają: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Twoje klucze są szyfrowane w bazie danych tej witryny i są wysyłane wyłącznie do wybranego dostawcy — nigdy do nas.','Step 1 of 2: choose an AI provider'=>'Krok 1 z 2: wybierz dostawcę AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Dostarczasz własny klucz, więc płacisz dostawcy bezpośrednio za to, z czego korzystasz. Nie masz pewności? Każda z tych opcji sprawdzi się dobrze; w przyszłości możesz dodać kolejne.','Next'=>'Dalej','Step 2 of 2: connect %s'=>'Krok 2 z 2: połącz z %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Wprowadź adres swojej usługi kompatybilnej z OpenAI, kończący się na /v1. Klucz jest wymagany tylko wtedy, gdy usługa go żąda.','Open %s and sign in (or create a free account).'=>'Otwórz %s i zaloguj się (lub utwórz darmowe konto).','the %s API keys page'=>'strona kluczy API %s','Create a new key and copy it.'=>'Utwórz nowy klucz i skopiuj go.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Wklej je poniżej i kliknij „Zapisz i przetestuj”. Wyślemy jedno małe żądanie, aby sprawdzić, czy to działa.','Most providers need a little credit on the account before a key works: %s.'=>'Większość dostawców wymaga niewielkich środków na koncie, zanim klucz zacznie działać: %s.','add credit'=>'dodaj środki','← Choose a different provider'=>'← Wybierz innego dostawcę','Address'=>'Adres','Saved key ends in …%s — paste a new one to replace it'=>'Zapisany klucz kończy się na …%s — wklej nowy, aby go zastąpić','Key (optional)'=>'Klucz (opcjonalnie)','API key'=>'Klucz API','Save and test'=>'Zapisz i przetestuj','Providers'=>'Dostawcy','Provider'=>'Dostawca','Status'=>'Status','Key'=>'Klucz','Get a key'=>'Pobierz klucz','Test'=>'Test','Remove'=>'Usuń','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Zapisano za pomocą nowszej wersji wtyczki: zaktualizuj tę wtyczkę lub wpisz klucz ponownie.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Zapisanego klucza nie można już otworzyć (klucze zabezpieczeń witryny uległy zmianie). Wprowadź go ponownie.','Not connected'=>'Nie połączono','Connected — last test passed %s'=>'Połączono – ostatni test powiódł się %s','Last test failed: %s'=>'Ostatni test nie powiódł się: %s','Connected — not tested yet'=>'Połączono — jeszcze nie przetestowano','Which model to use'=>'Który model użyć','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ oznacza naszą rekomendację dla tego zadania. Lista zawiera każdy model, z którego może korzystać Twój klucz, pobierany na żywo od dostawcy.','— Recommended for the provider —'=>'— Zalecane przez dostawcę —','Save models'=>'Zapisz modele','Refresh the model lists from the providers'=>'Odśwież listy modeli od dostawców','best quality'=>'najwyższa jakość','lowest cost'=>'najniższy koszt','fastest'=>'najszybsze','Add a model yourself'=>'Dodaj model samodzielnie','A model came out today? Paste its exact name to use it straight away.'=>'Pojawił się dzisiaj nowy model? Wklej jego dokładną nazwę, aby zacząć z niego od razu korzystać.','Model name'=>'Nazwa modelu','Add model'=>'Dodaj model','Recommended models list'=>'Lista polecanych modeli','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Nie udało się zweryfikować listy polecanych modeli, więc nie wyświetlono żadnych rekomendacji. Zainstaluj wtyczkę ponownie lub włącz codzienne aktualizacje poniżej.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Używana lista została opublikowana %s. Każda aktualizacja wtyczki przynosi nową.','Also check Zinn Digital® once a day for an updated list.'=>'Sprawdzaj również Zinn Digital® raz dziennie, aby uzyskać zaktualizowaną listę.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Wysyłane jest wyłącznie zwykłe żądanie pobrania: brak klucza, adresu strony i jakichkolwiek informacji o treści. Lista jest podpisana, a lista, która nie przejdzie pomyślnie weryfikacji podpisu, jest ignorowana.','Last checked %1$s: %2$s.'=>'Ostatnio sprawdzano %1$s: %2$s.','Save, and check now if turned on'=>'Zapisz i sprawdź teraz, jeśli włączono','a newer list was installed'=>'zainstalowano nowszą listę','already up to date'=>'najbardziej aktualna','the download failed the signature check and was ignored'=>'pobieranie nie przeszło weryfikacji podpisu i zostało zignorowane','Zinn Digital® could not be reached; the current list stays in use'=>'Nie można było połączyć się z Zinn Digital®; bieżąca lista pozostaje w użyciu','turned off'=>'wyłączone','Open'=>'Otwórz','Check their status page'=>'Sprawdź ich stronę statusu','Open your billing page'=>'Otwórz stronę rozliczeniową','Open your API keys page'=>'Otwórz stronę kluczy API','Open the AI settings'=>'Otwórz ustawienia AI','Sorry, you are not allowed to do that.'=>'Przepraszamy, nie masz do tego uprawnień.','Unknown provider.'=>'Nieznany dostawca.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Wprowadź adres swojego serwisu, na przykład http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To nie wygląda na klucz API. Skopiuj go ponownie, bez spacji.','Paste your API key first.'=>'Najpierw wklej swój klucz API.','Key removed.'=>'Klucz usunięty.','Models saved.'=>'Zapisano modele.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Wprowadź dokładnie nazwę modelu, na przykład tak, jak jest podana w dokumentacji dostawcy.','Added %s. Choose it under "Which model to use".'=>'Dodano %s. Wybierz go w sekcji „Którego modelu użyć”.','Model removed.'=>'Usunięto model.','Daily updates are off. The list that came with the plugin is used.'=>'Codzienne aktualizacje są wyłączone. Używana jest lista dołączona do wtyczki.','Checked: %s.'=>'Zaznaczono: %s.','Model lists refreshed.'=>'Odświeżono listy modeli.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Twój klucz AI został zapisany przez nowszą wersję jednej z wtyczek. Zaktualizuj tę wtyczkę lub wprowadź klucz ponownie w ustawieniach AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Twój zapisany klucz AI nie może być już odczytany (klucze bezpieczeństwa witryny uległy zmianie). Wprowadź go ponownie w ustawieniach AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Sztuczna inteligencja nie jest jeszcze skonfigurowana. Dodaj klucz dostawcy sztucznej inteligencji w ustawieniach AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Nie wybrano modelu dla tego zadania. Wybierz jeden w ustawieniach AI.','That AI provider is not supported by this version of the plugin.'=>'Ten dostawca sztucznej inteligencji nie jest obsługiwany przez tę wersję wtyczki.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ta strona nie mogła połączyć się z usługą AI. Sprawdź, czy usługa działa i czy jej adres jest osiągalny z serwera WWW (usługa na Twoim własnym komputerze jest niedostępna dla strony hostowanej).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ta witryna nie mogła połączyć się z %s. Sprawdź jej stronę statusu; jeśli działa, Twój hosting może blokować połączenia wychodzące lub adres jest błędny.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s informuje, że Twoje konto nie ma już środków lub limitu. Dodaj środki lub zwiększ limit na swoim koncie u nich, a następnie spróbuj ponownie.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'Usługa %s odrzuciła Państwa klucz. Mogł on zostać błędnie wpisany, unieważniony lub jego ważność wygasła. Proszę utworzyć nowy klucz i wkleić go tutaj.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s odrzuciło to żądanie dotyczące Twojego klucza. Klucz może nie mieć dostępu do tego modelu lub funkcji bądź Twoje konto wymaga weryfikacji.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" jest niedostępny w usłudze %2$s dla Twojego klucza. Wybierz inny model w ustawieniach sztucznej inteligencji.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Twój plan %2$s nie zawiera modelu „%1$s”. Wybierz inny model w ustawieniach sztucznej inteligencji lub uaktualnij swój plan u nich.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ogranicza szybkość wysyłania żądań przez Twój klucz. Odczekaj minutę i spróbuj ponownie lub zwiększ u nich swój limit zapytań.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s ma obecnie problemy (awaria lub przeciążenie po ich stronie). Twoje ustawienia są w porządku. Spróbuj ponownie za chwilę.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Żądanie AI nie powiodło się z nieznanej przyczyny. Spróbuj ponownie; jeśli problem będzie się powtarzał, skontaktuj się z pomocą techniczną, podając poniższe szczegóły.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Dostawca sztucznej inteligencji odpowiedział wformacie, którego ta wtyczka nie potrafi odczytać. Spróbuj ponownie; jeśli problem będzie się powtarzał, wybierz inny model lub skontaktuj się zpomocą techniczną.','Custom (OpenAI-compatible)'=>'Niestandardowy (zgodny z OpenAI)','Save a key for this provider first.'=>'Najpierw zapisz klucz dla tego dostawcy.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Twój klucz działa, ale dostawca nie podaje dla niego żadnego modelu tekstowego. Dodaj model samodzielnie poniżej.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Połączono. %1$s odpowiedział za pomocą %2$s. Funkcje sztucznej inteligencji są gotowe do użycia.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Twoja rola użytkownika nie ma uprawnień do korzystania ze sztucznej inteligencji w tej witrynie. Skontaktuj się z administratorem.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ta witryna osiągnęła miesięczny limit wydatków na sztuczną inteligencję. Administrator może go zwiększyć w ustawieniach AI.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ta strona osiągnęła miesięczny limit żądań AI. Administrator może go zwiększyć w ustawieniach AI.','Usage and cost'=>'Użycie i koszty','The log, limits and role permissions apply to AI used through: %s.'=>'Dziennik, limity i uprawnienia ról dotyczą sztucznej inteligencji używanej za pośrednictwem: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Koszty są szacunkowe i zostały obliczone na podstawie opublikowanych cen; model o nieznanej cenie liczy się jako zero.','This month: %1$s requests, about %2$s.'=>'W tym miesiącu: %1$s żądań, około %2$s.','When'=>'Kiedy','Who'=>'Kto','Used for'=>'Używane do','Model'=>'Model','Tokens in / out'=>'Tokeny wejściowe / wyjściowe','About'=>'Informacje','Result'=>'Wynik','No AI requests have been made yet.'=>'Nie wykonano jeszcze żadnych żądań sztucznej inteligencji.','Done'=>'Gotowe','Limits and permissions'=>'Limity i uprawnienia','Monthly spending limit (US dollars)'=>'Miesięczny limit wydatków (dolarach US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Pozostaw puste, aby usunąć limit. Sztuczna inteligencja przestanie odpowiadać do końca miesiąca, gdy szacowany koszt go osiągnie.','Monthly request limit'=>'Limit miesięcznych zapytań','Leave empty for no limit.'=>'Pozostaw puste, aby nie wprowadzać limitu.','Who may use AI'=>'Kto może korzystać ze sztucznej inteligencji','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Zaznacz opcję „żadne”, aby pozwolić wszystkim użytkownikom mogącym korzystać z funkcji wtyczki na używanie AI. Administratorzy mogą z niej korzystać zawsze.','Save limits and permissions'=>'Zapisz limity i uprawnienia','Limits and permissions saved.'=>'Zapisano limity i uprawnienia.','That language is not one of this site\'s languages.'=>'Ten język nie jest jednym z języków tej witryny.','A translation must be the same kind of content as the original.'=>'Tłumaczenie musi być tego samego rodzaju treścią co oryginał.','Choose one of the site\'s other languages.'=>'Wybierz jeden z pozostałych języków witryny.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skrypty ekranu administratora są niedostępne w tej kopii wtyczki. Zainstaluj ją ponownie z wydanego pakietu.','This screen needs JavaScript.'=>'Ten ekran wymaga obsługi języka JavaScript.','Choose a language'=>'Wybierz język','Upgrade'=>'Uaktualnij','Pricing'=>'Cennik','Start Trial'=>'Rozpocznij okres próbny','Account'=>'Konto','Contact Us'=>'Kontakt','Affiliation'=>'Powiązanie','the kind of softwarePlugin'=>'Wtyczka','greetingHey %s,'=>'Witaj %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Zapisz się, aby otrzymywać powiadomienia e-mail dotyczące aktualizacji zabezpieczeń i funkcji, materiałów edukacyjnych oraz okazjonalnych ofert, a także aby udostępnić podstawowe informacje o środowisku WordPress. Pomoże nam to uczynić %s bardziej kompatybilnym z Twoją witryną i lepiej dostosowanym do Twoich potrzeb.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Wyraź zgodę na otrzymywanie powiadomień e-mail dotyczących aktualizacji zabezpieczeń i funkcji, materiałów edukacyjnych oraz okazjonalnych ofert, a także na udostępnianie podstawowych informacji o środowisku WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Jeśli to pominiesz, nic nie szkodzi! %1$s nadal będzie działać bez zarzutu.','Allow & Continue'=>'Zezwól i kontynuuj','verbSkip'=>'Pomiń','Skipping, please wait'=>'Pomijanie, proszę czekać','Continue'=>'Kontynuuj','Please wait'=>'Proszę czekać','as activating pluginActivating'=>'Aktywowanie','This will allow %s to'=>'To pozwoli %s na','Privacy Policy'=>'Polityka prywatności','Terms of Service'=>'Warunki korzystania z usługi','License Agreement'=>'Umowa licencyjna','Have a license key?'=>'Masz klucz licencyjny?','Activate License'=>'Aktywuj licencję','View Basic Profile Info'=>'Wyświetl podstawowe informacje profilu','Your WordPress user\'s: first & last name, and email address'=>'Imię i nazwisko oraz adres e-mail użytkownika WordPressa','View Basic Website Info'=>'Wyświetl podstawowe informacje o witrynie','Homepage URL & title, WP & PHP versions, and site language'=>'Adres URL i tytuł strony głównej, wersje WP i PHP oraz język witryny','View Basic %s Info'=>'Wyświetl podstawowe informacje o %s','Current %s & SDK versions, and if active or uninstalled'=>'Obecne wersje %s i SDK oraz informacja, czy są aktywne lub odinstalowane','Newsletter'=>'Biuletyn','Updates, announcements, marketing, no spam'=>'Aktualizacje, ogłoszenia, marketing, zero spam-u','View Diagnostic Info'=>'Wyświetl informacje diagnostyczne','WordPress & PHP versions, site language & title'=>'Wersje WordPress i PHP, język i tytuł witryny','View Plugins & Themes List'=>'Wyświetl listę wtyczek i motywów','Names, slugs, versions, and if active or not'=>'Nazwy, odnośniki (slug), wersje oraz informacje o tym, czy element jest aktywny, czy nie','optional'=>'opcjonalne','Never miss an important update'=>'Nigdy nie przegap ważnej aktualizacji','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Wprowadziliśmy tę opcję, abyś nigdy nie przegapił ważnej aktualizacji i pomógł nam uczynić %s bardziej kompatybilnym z Twoją witryną oraz lepszym w spełnianiu Twoich potrzeb.','Thank you for updating to %1$s v%2$s!'=>'Dziękujemy za aktualizację do wersji %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Przedrostek musi składać się z od 1 do 8 małych liter lub cyfr, zaczynać się od litery i nie może pokrywać się z nazwą wtyczki.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" nie jest kodem języka. Użyj ustawień regionalnych WordPress, takich jak fr_FR lub de_DE.','List at least one language.'=>'Wymień co najmniej jeden język.','You are not allowed to translate this item.'=>'Nie masz uprawnień do tłumaczenia tego elementu.','This item already has a version in that language.'=>'Ten element ma już wersję w tym języku.','The value for %s is not one of the allowed choices.'=>'Wartość dla %s nie znajduje się na liście dozwolonych opcji.','This item\'s group already has a %1$s version (#%2$d).'=>'Grupa tego elementu ma już wersję %1$s (#%2$d).','An item cannot be its own translation.'=>'Element nie może być swoim własnym tłumaczeniem.','That item is already a translation of something else. Unlink it first.'=>'Ten element jest już tłumaczeniem czegoś innego. Najpierw odłącz go.','The translation link could not be saved.'=>'Nie udało się zapisać łącza tłumaczenia.','That text cannot be translated here.'=>'Tego tekstu nie można tutaj przetłumaczyć.','That media text cannot be translated here.'=>'Tego tekstu medialnego nie można tutaj przetłumaczyć.','A translation can be published or kept as a draft.'=>'Tłumaczenie może zostać opublikowane lub zachowane jako wersja robocza.','You are not allowed to publish this kind of content.'=>'Nie masz uprawnień do publikowania tego rodzaju treści.','This item is already written in that language.'=>'Ten element jest już napisany w tym języku.','You are not allowed to change that translation.'=>'Nie wolno Ci zmienić tego tłumaczenia.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'To tłumaczenie zostało edytowane przez człowieka (lub zaimportowane), więc jest chronione. Odblokuj je, aby przetłumaczyć je ponownie.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Nie skonfigurowano jeszcze żadnego silnika tłumaczeń. Dodaj klucz dla jednego z nich w sekcji Tranzly → Silniki.','That translation engine is not available on this site.'=>'Ten silnik tłumaczący nie jest dostępny w tej witrynie.','That translation engine is not set up yet: add its key first.'=>'Ten silnik tłumaczeń nie został jeszcze skonfigurowany: dodaj najpierw jego klucz.','%s did not return a translation for every part of this item. Nothing was changed.'=>'%s nie zwrócił tłumaczenia dla każdego elementu tego przedmiotu. Nic nie zostało zmienione.','An engine id must be lowercase letters, digits and hyphens.'=>'Identyfikator silnika musi składać się wyłącznie z małych liter, cyfr i myślników.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Stworzone przez Neil Lock, CEO Zinn Digital® Ltd','Version %s'=>'Wersja %s','Tranzly website'=>'Strona internetowa Tranzly','Zinn Digital® website'=>'witryna Zinn Digital®','Settings saved.'=>'Ustawienia zostały zapisane.','See the Pro plans and pricing'=>'Zobacz plany Pro i cennik','Languages'=>'Języki','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'Pierwszy język to ten, w którym napisana jest Twoja treść. Odwiedzający mogą przełączać się za pomocą bloku przełącznika języka.','(default)'=>'(domyślnie)','Locale code'=>'Kod ustawień regionalnych','For example fr_FR'=>'Na przykład fr_FR','Name (optional)'=>'Nazwa (opcjonalnie)','For example Français'=>'Na przykład Français','Add language'=>'Dodaj język','Front-end output'=>'Wyjście interfejsu','Class name prefix'=>'Prefiks nazwy klasy','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Każda nazwa klasy, którą wtyczka umieszcza na Twoich stronach, zaczyna się od tego prefisku, dzięki czemu strony nie zdradzają, która wtyczka je utworzyła. Od 1 do 8 małych liter lub cyfr, zaczynając od litery.','Beta updates'=>'Aktualizacje beta','This site receives beta versions as updates.'=>'Ta witryna otrzymuje wersje beta jako aktualizacje.','This site receives stable versions only.'=>'Ta strona otrzymuje tylko stabilne wersje.','Change this on the Account page'=>'Zmień to na stronie Konta','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Wersje beta są oferowane licencjonowanym instalacjom Pro, które są powiązane z ich kontem. Po połączeniu możesz dołączyć ze strony Konta.','Save settings'=>'Zapisz ustawienia','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Dodaj drugi język w sekcji Tranzly w menu administracyjnym, a przełącznik pojawi się tutaj.','Switcher'=>'Przełącznik','Accessible label'=>'Etykieta dostępności','block titleLanguage switcher'=>'Przełącznik języka','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Linki do tej strony w każdym z języków witryny. Nic nie wyświetla się, dopóki nie zostaną wymienione co najmniej dwa języki.','block keywordlanguage'=>'Język','block keywordswitcher'=>'Przełącznik','block keywordtranslation'=>'tłumaczenie']];